import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// ════════════════════════════════════════════════════════════
// 仙剑奇侠传1 MVU schema.ts
// 与 initvar.yaml 9 个命名空间对齐：时间/场景/主角/队伍/角色/世界/临时/战斗/时间与位置
// ════════════════════════════════════════════════════════════

const Schema = z.object({
  // ─── 时间（5 个） ───
  时间: z.object({
    游戏日期: z.coerce.string().prefault('仙剑历0001年01月01日'),
    时段: z.enum(['早','午','晚','夜']).prefault('早'),
    天数: z.coerce.number().transform(v => _.clamp(Math.round(v), 1, 60)).prefault(1),
    天气: z.enum(['晴','阴','雨','雪','雾','风']).prefault('晴'),
    当前时间: z.coerce.string().prefault('08:00')
  }).prefault({}),

  // ─── 场景（4 个） ───
  场景: z.object({
    当前地点: z.coerce.string().prefault('余杭镇客栈'),
    场景模式: z.enum(['探索','对话','战斗','事件','休息','旅行']).prefault('探索'),
    当前章节: z.coerce.number().transform(v => _.clamp(Math.round(v), 1, 6)).prefault(1),
    章节进度: z.coerce.number().transform(v => _.clamp(Math.round(v), 1, 60)).prefault(1)
  }).prefault({}),

  // ─── 主角（14 核心 + 4 嵌套命名空间） ───
  主角: z.object({
    // 核心字段（14 个）
    姓名: z.coerce.string().prefault('李逍遥'),
    等级: z.coerce.number().transform(v => _.clamp(Math.round(v), 1, 99)).prefault(1),
    HP: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 9999)).prefault(100),
    MP: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 999)).prefault(30),
    武术: z.coerce.number().transform(v => _.clamp(Math.round(v), 1, 255)).prefault(16),
    体质: z.coerce.number().transform(v => _.clamp(Math.round(v), 1, 255)).prefault(16),
    灵力: z.coerce.number().transform(v => _.clamp(Math.round(v), 1, 255)).prefault(15),
    根骨: z.coerce.number().transform(v => _.clamp(Math.round(v), 1, 255)).prefault(14),
    身法: z.coerce.number().transform(v => _.clamp(Math.round(v), 1, 255)).prefault(17),
    吉运: z.coerce.number().transform(v => _.clamp(Math.round(v), 1, 255)).prefault(13),
    经验: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 9999999)).prefault(0),
    下一级经验: z.coerce.number().transform(v => _.clamp(Math.round(v), 1, 9999999)).prefault(100),
    体力: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 100)).prefault(80),
    心情: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 100)).prefault(70),

    // ─── 主角.资产（3 个） ───
    资产: z.object({
      铜钱: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 9999999)).prefault(500),
      灵玉库存: z.record(z.string(), z.coerce.number()).prefault({}),
      装备: z.object({
        武器: z.coerce.string().prefault('木剑'),
        防具: z.coerce.string().prefault('布衣'),
        配饰: z.string().nullable().prefault(null)
      }).prefault({})
    }).prefault({}),

    // ─── 主角.装备灵玉槽（2 数组） ───
    装备灵玉槽: z.object({
      武器灵玉槽: z.array(z.string().nullable()).prefault([null, null]),
      防具灵玉槽: z.array(z.string().nullable()).prefault([null])
    }).prefault({}),

    // ─── 主角.剑法（5 个·0-100） ───
    剑法: z.object({
      万剑诀: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 100)).prefault(0),
      天剑: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 100)).prefault(0),
      酒神咒: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 100)).prefault(0),
      逍遥神剑: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 100)).prefault(0),
      绝技槽: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 4)).prefault(0)
    }).prefault({}),

    // ─── 主角.状态（3 个） ───
    状态: z.object({
      中毒: z.coerce.boolean().prefault(false),
      走火入魔: z.coerce.boolean().prefault(false),
      觉醒阶段: z.enum(['凡胎','初觉','半觉','觉醒','圆满']).prefault('凡胎')
    }).prefault({})
  }).prefault({}),

  // ─── 队伍（2 个） ───
  队伍: z.object({
    成员: z.array(z.coerce.string()).prefault(['李逍遥']),
    队长: z.coerce.string().prefault('李逍遥')
  }).prefault({}),

  // ─── 角色（3 女主角） ───
  角色: z.object({
    赵灵儿: z.object({
      好感度: z.coerce.number().transform(v => _.clamp(Math.round(v), -100, 100)).prefault(0),
      关系阶段: z.enum(['初识','友好','暧昧','恋爱','结拜','敌对','决裂']).prefault('初识'),
      是否加入队伍: z.coerce.boolean().prefault(false)
    }).prefault({}),
    林月如: z.object({
      好感度: z.coerce.number().transform(v => _.clamp(Math.round(v), -100, 100)).prefault(0),
      关系阶段: z.enum(['初识','友好','暧昧','恋爱','结拜','敌对','决裂']).prefault('初识'),
      是否加入队伍: z.coerce.boolean().prefault(false)
    }).prefault({}),
    阿奴: z.object({
      好感度: z.coerce.number().transform(v => _.clamp(Math.round(v), -100, 100)).prefault(0),
      关系阶段: z.enum(['初识','友好','暧昧','恋爱','结拜','敌对','决裂']).prefault('初识'),
      是否加入队伍: z.coerce.boolean().prefault(false)
    }).prefault({})
  }).prefault({}),

  // ─── 世界（5 个） ───
  世界: z.object({
    当前章节: z.coerce.number().transform(v => _.clamp(Math.round(v), 1, 6)).prefault(1),
    章节进度: z.coerce.number().transform(v => _.clamp(Math.round(v), 1, 60)).prefault(1),
    已完成事件: z.array(z.coerce.string()).prefault([]),
    当前世界线: z.enum(['原著线','改写线']).prefault('原著线'),
    已改写事件: z.array(z.coerce.string()).prefault([])
  }).prefault({}),

  // ─── 临时（3 个） ───
  临时: z.object({
    当前难度: z.enum(['轻松','普通','挑战','地狱']).prefault('普通'),
    本时段楼层数: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 99)).prefault(0),
    连续大失败次数: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 99)).prefault(0)
  }).prefault({}),

  // ─── 战斗（6 个） ───
  战斗: z.object({
    敌方名称: z.string().nullable().prefault(null),
    敌方HP: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 99999)).prefault(0),
    敌方MaxHP: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 99999)).prefault(0),
    回合数: z.coerce.number().transform(v => _.clamp(Math.round(v), 0, 999)).prefault(0),
    是否BOSS战: z.coerce.boolean().prefault(false),
    战斗状态: z.enum(['和平','战斗中','胜利','失败','逃跑']).prefault('和平')
  }).prefault({}),

  // ─── 时间与位置（3 个·综合状态镜像） ───
  时间与位置: z.object({
    游戏日期: z.coerce.string().prefault('仙剑历0001年01月01日'),
    时段: z.enum(['早','午','晚','夜']).prefault('早'),
    当前地点: z.coerce.string().prefault('余杭镇客栈')
  }).prefault({})
}).prefault({});

$(() => {
  registerMvuSchema(Schema);
});

// 远楼层消息隐藏脚本占位（具体内容由 脚本/楼层隐藏.txt 提供）
// 也可使用 SillyTavern 自带的楼层隐藏功能
(() => {})();

entries.content:
@@generate_before
<%/* ════════════════════════════════════════════════════════════
   仙剑奇侠传1 · 全局规则-剑法绝技系统（扩展模块·按需加载）
   ════════════════════════════════════════════════════════════
   职责：剑法绝技系统规则（5类武器 + 熟练度5等 + 绝技槽 + 角色绝技谱 + 伤害公式 + 触发条件）
   加载策略：由主调度控制器按 战斗状态/章节 条件加载
   依赖：需先加载「全局规则总表.txt」的 var 兜底声明
   define() 模式：注册 SWORD_SYSTEM 全局常量，供战斗指令调度器/角色条目调用
   ════════════════════════════════════════════════════════════ */%>

<%
/* ───────── 读取 MVU 当前运行时状态（供摘要动态输出）───────── */
if (typeof li_prof === 'undefined') var li_prof = Number(getvar('stat_data.剑法.李逍遥.剑法熟练度', { scope: 'local', defaults: 0 })) || 0;
if (typeof lin_prof === 'undefined') var lin_prof = Number(getvar('stat_data.剑法.林月如.鞭法熟练度', { scope: 'local', defaults: 0 })) || 0;
if (typeof anu_prof === 'undefined') var anu_prof = Number(getvar('stat_data.剑法.阿奴.暗器熟练度', { scope: 'local', defaults: 0 })) || 0;
if (typeof li_slot === 'undefined') var li_slot = Number(getvar('stat_data.剑法.李逍遥.绝技槽', { scope: 'local', defaults: 0 })) || 0;
if (typeof lin_slot === 'undefined') var lin_slot = Number(getvar('stat_data.剑法.林月如.绝技槽', { scope: 'local', defaults: 0 })) || 0;
if (typeof anu_slot === 'undefined') var anu_slot = Number(getvar('stat_data.剑法.阿奴.绝技槽', { scope: 'local', defaults: 0 })) || 0;

/* ════════════════════════════════════════════════════════════
   一、武器类型与熟练度（5类武器）
   ════════════════════════════════════════════════════════════ */
const SWORD_SYSTEM = {
  weapon_types: {
    剑: {
      name: '剑', school: '蜀山派', default_user: '李逍遥',
      desc: '蜀山剑法正统，攻守兼备，以气御剑。可学万剑诀/天剑/剑神三级绝技',
      stat_key: '剑法熟练度', growth_actions: ['蜀山练剑', '实战磨砺', '剑意参悟']
    },
    鞭: {
      name: '鞭', school: '林家堡', default_user: '林月如',
      desc: '柔性长兵器，缠绕抽打，攻防一体。可学鞭卷长风/绕指柔/烈火鞭/雷霆万钧',
      stat_key: '鞭法熟练度', growth_actions: ['林家鞭法', '比武切磋', '雷霆淬炼']
    },
    暗器: {
      name: '暗器', school: '苗疆', default_user: '阿奴',
      desc: '蛊毒暗器，可附带持续伤害与异常状态。可学三尸虫/化尸粉/万蛊噬心',
      stat_key: '暗器熟练度', growth_actions: ['蛊毒研习', '暗器靶练', '苗疆秘术']
    },
    杖: {
      name: '杖', school: '法术系', default_user: '通用',
      desc: '法杖媒介，增强五灵法术威力与范围，法术系角色专用',
      stat_key: '杖法熟练度', growth_actions: ['法杖修习', '五灵冥想', '法阵演练']
    },
    拳: {
      name: '拳', school: '酒剑仙', default_user: '酒剑仙/李逍遥',
      desc: '醉拳拳法，不依赖兵器，酒剑仙一脉传承，醉态出招难以捉摸',
      stat_key: '拳法熟练度', growth_actions: ['醉拳演练', '饮酒悟拳', '酒剑仙点拨']
    }
  },

  /* ════════════════════════════════════════════════════════════
     二、熟练度等级（5档，决定绝技倍率与可用绝技）
     ════════════════════════════════════════════════════════════ */
  proficiency_stages: {
    0: { name: '初学', range: [0, 100],     multiplier: 0.8, desc: '刚入门，招式生疏，仅可触发初级绝技' },
    1: { name: '入门', range: [101, 300],   multiplier: 1.2, desc: '基础招式熟练，可触发初级绝技，伤害稳定' },
    2: { name: '小成', range: [301, 600],   multiplier: 1.8, desc: '招式连贯，可触发中级绝技，伤害可观' },
    3: { name: '大成', range: [601, 1000],  multiplier: 2.5, desc: '招式精妙，可触发高级绝技，伤害爆表' },
    4: { name: '化境', range: [1001, 99999], multiplier: 2.5, desc: '人器合一，绝技威力最大化，附加特效' }
  },

  /* ════════════════════════════════════════════════════════════
     三、绝技槽系统（满100触发，可累积至300三连发）
     ════════════════════════════════════════════════════════════ */
  skill_slot: {
    trigger_threshold: 100,
    max_accumulation: 300,
    max_combo: 3,
    gain_rules: {
      受击: '+5（每次被攻击）',
      格挡: '+8（成功格挡）',
      暴击: '+15（打出暴击）',
      击杀: '+30（击杀敌人）',
      受伤达标: '+30（受伤≥30%HP时一次性获得）',
      队友濒死: '+50（队友HP<20%时每回合获得）'
    },
    decay_rule: '每回合未使用绝技，槽值衰减10（不低于0）',
    overflow_rule: '超过300部分溢出无效；使用时按100/次消耗',
    combo_bonus: '连发加成：每多消耗100槽，伤害倍率叠加×1.1（三连发总加成×1.21）'
  },

  /* ════════════════════════════════════════════════════════════
     四、角色绝技谱
     ════════════════════════════════════════════════════════════ */
  skill_trees: {
    李逍遥: {
      蜀山基础剑法: [
        { name: '万剑诀', stage_req: 1, cost: 100, desc: '蜀山入门剑法，以气御剑，剑气分化数道齐发，群体中伤' },
        { name: '天剑',   stage_req: 2, cost: 100, desc: '蜀山中级剑法，剑气凝为光刃，单体高伤' },
        { name: '剑神',   stage_req: 3, cost: 200, desc: '蜀山顶级剑法，剑意通神，群体绝杀，无视部分防御' }
      ],
      酒剑仙传授: [
        { name: '醉剑式', stage_req: 1, cost: 100, desc: '酒剑仙所授，醉态出剑，闪避后反击，单体中伤+自身闪避提升' },
        { name: '酒神咒', stage_req: 2, cost: 200, desc: '酒剑仙所授，以酒为引，引动天地之力，群体灼伤+持续燃烧' }
      ],
      觉醒绝技: [
        { name: '逍遥神剑', stage_req: 4, cost: 300, desc: '女娲血脉共鸣觉醒绝技，融合蜀山剑意与女娲神力，单体终极绝杀，无视防御',
          condition: '女娲血脉觉醒阶段 ≥ 2' }
      ]
    },
    林月如: {
      鞭法: [
        { name: '鞭卷长风', stage_req: 1, cost: 100, desc: '长鞭横扫，群体轻伤+击退' },
        { name: '绕指柔',   stage_req: 1, cost: 100, desc: '鞭梢缠绕单体，缴械控制一回合' },
        { name: '烈火鞭',   stage_req: 2, cost: 200, desc: '鞭附火灵之力，单体灼伤+持续燃烧3回合' },
        { name: '雷霆万钧', stage_req: 3, cost: 200, desc: '雷霆注入长鞭，群体雷击+麻痹' }
      ]
    },
    阿奴: {
      蛊术攻击: [
        { name: '三尸虫',   stage_req: 1, cost: 100, desc: '放蛊三尸虫，单体持续扣血3回合' },
        { name: '化尸粉',   stage_req: 2, cost: 100, desc: '腐蚀性毒粉，单体防御降低50%+持续中毒' },
        { name: '万蛊噬心', stage_req: 3, cost: 200, desc: '万蛊齐出噬心，群体持续伤害+混乱2回合' }
      ]
    }
  },

  /* ════════════════════════════════════════════════════════════
     五、绝技伤害公式
     ════════════════════════════════════════════════════════════ */
  damage_formula: {
    formula: '基础伤害 = 武力 × (1 + 熟练度/1000) × 绝技倍率 × (1 - 目标防御/1000)',
    variables: {
      武力: '角色当前武力值（含装备加成）',
      熟练度: '对应武器类型的当前熟练度值',
      绝技倍率: '按熟练度等级查 proficiency_stages[].multiplier（0.8/1.2/1.8/2.5）',
      目标防御: '目标物理防御值（0-1000）'
    },
    skill_multipliers: { 初学: 0.8, 入门: 1.2, 小成: 1.8, 大成: 2.5, 化境: 2.5 },
    extra_rules: [
      '化境附加特效：剑系无视50%防御 / 鞭系追加麻痹 / 暗器系追加剧毒 / 杖系法术增幅30% / 拳系必暴击',
      '绝技连发：每多消耗100槽，伤害倍率叠加×1.1（三连发最高×1.21总加成）',
      '暴击：基础伤害×1.5（独立计算，最后乘）',
      '属性克制：五灵相克时伤害×1.2，被克时×0.8'
    ]
  },

  /* ════════════════════════════════════════════════════════════
     六、绝技触发条件
     ════════════════════════════════════════════════════════════ */
  trigger_conditions: {
    '受伤≥30%HP': {
      desc: '角色当前HP损失达到最大HP的30%以上时，绝技槽获得+30充能',
      check: 'current_hp <= max_hp × 0.7',
      slot_gain: 30,
      forced: false,
      once_per_turn: true
    },
    '队友濒死': {
      desc: '队伍中有队友HP低于20%时，绝技槽获得+50充能（每回合判定一次）',
      check: 'any_ally.hp <= ally.max_hp × 0.2',
      slot_gain: 50,
      forced: false,
      once_per_turn: true
    },
    '章节BOSS战': {
      desc: '章节BOSS战开启时，所有参战角色绝技槽直接充满至100',
      check: 'enemy.is_boss === true && chapter.boss_battle === true',
      slot_set: 100,
      forced: true,
      once_per_battle: true
    }
  },

  /* ════════════════════════════════════════════════════════════
     七、熟练度查询函数（供其他EJS条目调用）
     ════════════════════════════════════════════════════════════ */
  getStage: function (proficiency) {
    if (proficiency <= 100) return SWORD_SYSTEM.proficiency_stages[0];
    if (proficiency <= 300) return SWORD_SYSTEM.proficiency_stages[1];
    if (proficiency <= 600) return SWORD_SYSTEM.proficiency_stages[2];
    if (proficiency <= 1000) return SWORD_SYSTEM.proficiency_stages[3];
    return SWORD_SYSTEM.proficiency_stages[4];
  }
};

define('SWORD_SYSTEM', SWORD_SYSTEM);
%>

<%_ // ───────── 参考摘要（输出给AI使用）───────── _%>
<%_ const _li_stage = SWORD_SYSTEM.getStage(li_prof); _%>
<%_ const _lin_stage = SWORD_SYSTEM.getStage(lin_prof); _%>
<%_ const _anu_stage = SWORD_SYSTEM.getStage(anu_prof); _%>
【剑法绝技系统 · 参考摘要】

■ 武器类型（5类）
- 剑（蜀山派/李逍遥）：攻守兼备，万剑诀→天剑→剑神
- 鞭（林家堡/林月如）：缠绕抽打，鞭卷长风→绕指柔→烈火鞭→雷霆万钧
- 暗器（苗疆/阿奴）：蛊毒持续，三尸虫→化尸粉→万蛊噬心
- 杖（法术系/通用）：法杖媒介，增强五灵法术
- 拳（酒剑仙/李逍遥）：醉拳拳法，不依赖兵器

■ 熟练度等级（5档·决定绝技倍率）
- 初学（0-100）｜倍率0.8
- 入门（101-300）｜倍率1.2
- 小成（301-600）｜倍率1.8
- 大成（601-1000）｜倍率2.5
- 化境（1001+）｜倍率2.5（附加特效）

■ 绝技槽系统
- 触发阈值：100 ｜ 上限：300（三连发）｜ 未使用每回合衰减10
- 连发加成：每多消耗100槽 ×1.1叠加（三连发最高×1.21）

■ 伤害公式
基础伤害 = 武力 × (1 + 熟练度/1000) × 绝技倍率 × (1 - 目标防御/1000)
- 暴击×1.5（最后乘）｜ 五灵相克×1.2 / 被克×0.8
- 化境特效：剑系无视50%防御 / 鞭系麻痹 / 暗器系剧毒 / 杖系法术+30% / 拳系必暴击

■ 绝技触发条件
- 受伤≥30%HP → 槽+30
- 队友濒死(HP<20%) → 槽+50
- 章节BOSS战 → 槽直接充满100（强制）

■ 李逍遥剑法谱
- 蜀山基础剑法：万剑诀(初学+) / 天剑(小成+) / 剑神(大成+)
- 酒剑仙传授：醉剑式(入门+) / 酒神咒(小成+)
- 觉醒绝技：逍遥神剑(化境·需女娲血脉觉醒≥2)

■ 林月如鞭法
- 鞭卷长风(入门+) / 绕指柔(入门+) / 烈火鞭(小成+) / 雷霆万钧(大成+)

■ 阿奴蛊术攻击
- 三尸虫(入门+) / 化尸粉(小成+) / 万蛊噬心(大成+)

