  getChapterByProgress: function (progress) {
    var p = Number(progress) || 0;
    var ch = STAGE_FRAMEWORK.chapters;
    for (var k = 1; k <= 6; k++) {
      var r = ch[k].range;
      if (p >= r[0] && p <= r[1]) return ch[k];
    }
    if (p < 1)  return ch[1];
    return ch[6];
  },
  getChapterIndexByProgress: function (progress) {
    var p = Number(progress) || 0;
    var ch = STAGE_FRAMEWORK.chapters;
    for (var k = 1; k <= 6; k++) {
      var r = ch[k].range;
      if (p >= r[0] && p <= r[1]) return k;
    }
    if (p < 1)  return 1;
    return 6;
  },
  isEventCompleted: function (eventName) {
    if (!Array.isArray(_completedEvents)) return false;
    return _completedEvents.indexOf(eventName) !== -1;
  },
  canSwitchChapter: function (chapterIndex) {
    var ch = STAGE_FRAMEWORK.chapters[chapterIndex];
    if (!ch) return false;
    if (chapterIndex >= 6) return false;
    return STAGE_FRAMEWORK.isEventCompleted(ch.next_chapter_trigger);
  },
  nextChapterStartProgress: function (chapterIndex) {
    var next = chapterIndex + 1;
    var ch = STAGE_FRAMEWORK.chapters[next];
    if (!ch) return null;
    return ch.range[0];
  }
};

