<%- await getwi('D0指令/对话模式') %>
<% } else if (_sceneMode === '炼丹') { %>
<%- await getwi('D0指令/炼丹模式') %>
<% } else if (_sceneMode === '休憩') { %>
<%- await getwi('D0指令/休憩模式') %>
<% } else { %>
<%- await getwi('D0指令/探索模式') %>
