   9. 输出本轮场景合法性清单给 AI
   依赖：需先加载「全局规则总表.txt」的 var 兜底声明；LCG 骰子引擎可选
   ════════════════════════════════════════════════════════════ */%>

<%
/* ─── 1. 读取场景 MVU 变量 ─── */
const _scene = getvar('stat_data.场景', { scope: 'local', defaults: {} }) || {};
const _time = getvar('stat_data.时间', { scope: 'local', defaults: {} }) || {};
const _world = getvar('stat_data.世界', { scope: 'local', defaults: {} }) || {};
const _protag = getvar('stat_data.主角', { scope: 'local', defaults: {} }) || {};
const _temp = getvar('stat_data.临时', { scope: 'local', defaults: {} }) || {};

const _location = _scene.当前地点 || '余杭镇客栈';
const _chapter = Number(_world.当前章节) || 1;
const _tslot = _time.时段 || '早';
const _weather = _time.天气 || '晴';
const _sceneMode = _scene.场景模式 || '探索';
const _difficulty = _temp.当前难度 || '普通';

/* 主角状态 */
const _hp = Number(_protag.生命) || 100;
const _mp = Number(_protag.灵力) || 50;
const _lv = Number(_protag.等级) || 1;

/* ─── 2. 章节区域判定（6大章节） ─── */
function _resolveChapter(loc) {
  if (loc.includes('余杭') || loc.includes('客栈') || loc.includes('十里坡') || loc.includes('码头') || loc.includes('杂货铺')) return '余杭镇';
  if (loc.includes('仙灵') || loc.includes('灵月') || loc.includes('仙池') || loc.includes('灵脉') || loc.includes('渡口')) return '仙灵岛';
  if (loc.includes('苏州') || loc.includes('林家堡') || loc.includes('擂台') || loc.includes('比武') || loc.includes('商埠') || loc.includes('隐龙窟')) return '苏州';
  if (loc.includes('京城') || loc.includes('长安') || loc.includes('刘府') || loc.includes('皇宫') || loc.includes('财神庙')) return '京城';
  if (loc.includes('蜀山') || loc.includes('锁妖塔') || loc.includes('大殿') || loc.includes('祖师堂') || loc.includes('练剑场') || loc.includes('塔顶') || loc.includes('九层') || loc.includes('九幽') || loc.includes('囚室')) return '蜀山锁妖塔';
  if (loc.includes('苗疆') || loc.includes('白苗') || loc.includes('黑苗') || loc.includes('神木林') || loc.includes('祭坛') || loc.includes('王宫')) return '苗疆';
  return '余杭镇';
}
const _region = _resolveChapter(_location);

/* ─── 3. 商店物品查表 ─── */
const SHOP_ITEMS = (typeof SHOP_ITEMS !== 'undefined') ? SHOP_ITEMS : {
  '金创药':   { price: 50,   category: '药品', desc: '恢复少量生命，战斗中常用基础药' },
