  '还魂丹':   { price: 500,  category: '药品', desc: '复活濒死队友，珍稀道具' },
  '解毒丹':   { price: 80,   category: '药品', desc: '解除中毒与蛊毒状态' },
  '帐篷':     { price: 300,  category: '装备', desc: '野外露营恢复体力灵力' },
  '灵玉':     { price: 1000, category: '材料', desc: '灵力镶嵌载体，可镶嵌五灵' },
  '雄黄酒':   { price: 30,   category: '药品', desc: '解毒驱邪，苗疆常用' },
  '玉菩提':   { price: 800,  category: '材料', desc: '提升法术修为的稀有材料' }
};

const SHOP_BY_CHAPTER = (typeof SHOP_BY_CHAPTER !== 'undefined') ? SHOP_BY_CHAPTER : {
  '余杭镇':       ['金创药', '解毒丹', '帐篷', '雄黄酒'],
  '仙灵岛':       [],
