const BATTLE_DISPATCHER = {

  /* —— 1.1 战斗触发格式 —— */
  trigger: {
    format: '<BattleStart>敌名 | 战斗背景key | true/false</BattleStart>',
    fields: {
      '敌名':         '敌方NPC名称（或BOSS名称）',
      '战斗背景key':  '场景标识，如 "余杭镇_夜晚" / "隐龙窟_深处"',
      'true/false':   'true = BOSS战（启用 BOSS 规则） / false = 普通战'
    },
    parse: function (raw) {
      var s = String(raw || '').trim();
      var m = s.match(/^<BattleStart>\s*(.+?)\s*\|\s*(.+?)\s*\|\s*(true|false)\s*<\/BattleStart>$/i);
      if (!m) return null;
      return {
        敌名:       m[1].trim(),
