    { step: 4, name: '行动选择', desc: '普通攻击 / 法术 / 绝技 / 灵玉法术 / 蛊术 / 防御 / 逃跑（详见 actions）' },
    { step: 5, name: '战斗结束', desc: '敌方全灭（我方胜）/ 我方全灭（败，回到上一存档点）/ 逃跑成功（逃跑检定通过）' }
  ],

  /* —— 1.3 行动类型 —— */
  actions: {
    '普通攻击':  { desc: '武器直接攻击，按 SWORD_SYSTEM.damage_formula 计算伤害',                  cost: null,   cost_field: null },
    '法术':      { desc: '消耗灵力释放五灵法术，按 WULING_MAGIC_SYSTEM.damage_formula 计算',        cost: '灵力', cost_field: 'stat_data.属性.灵力' },
    '绝技':      { desc: '消耗绝技槽（≥100）释放，按 SWORD_SYSTEM.skill_trees 查询',                cost: '绝技槽', cost_field: 'stat_data.绝技槽' },
