    '蛊术':      { desc: '阿奴专属，施蛊/下毒/异常状态，按角色蛊术谱查询',                          cost: '蛊材', cost_field: 'stat_data.阿奴.蛊材' },
    '防御':      { desc: '本回合物理减伤 50%，绝技槽 +8，可反弹部分伤害',                          cost: null,   cost_field: null },
    '逃跑':      { desc: '逃跑检定（LCG 骰子 ≥ 41 可成功逃出），BOSS 战禁止逃跑',                   cost: null,   cost_field: null }
  },

  /* ════════════════════════════════════════════════════════════
     二、敌方 BOSS 表（按章节）
     ════════════════════════════════════════════════════════════ */
  boss_table: {
