        { name: '隐龙窟蛇妖',  hp: 720,  atk: 65,  def: 30, exp_base: 220, gold_base: 150, diff: '困难', drops: ['蛇胆', '解毒丹'] },
        { name: '毒蛊',        hp: 540,  atk: 55,  def: 18, exp_base: 180, gold_base: 120, diff: '困难', drops: ['蛊虫', '化尸粉残片'] }
