  },

  /* ════════════════════════════════════════════════════════════
     三、战斗结果结算公式
     ════════════════════════════════════════════════════════════ */
  result_formula: {
    经验值: {
      formula: '经验值 = 基础经验 × 难度系数 × LCG 档位倍率',
      tier_coeff: { '大失败': 0.2, '失败': 0.5, '普通': 1.0, '成功': 1.2, '大成功': 1.5, '暴击': 2.0 },
      path: 'stat_data.主角.经验.当前经验'
    },
    铜钱: {
      formula: '铜钱 = 基础铜钱 × 难度系数（取整）',
      note: 'BOSS 战额外 ×1.5',
      path: 'stat_data.主角.资产.铜钱'
    },
    灵玉AP: {
      formula: 'AP 增量 = 战斗回合数 × (1 + 难度系数)（BOSS 战额外 ×1.5）',
      note: '调用 SPIRITE_JADE_SYSTEM.calcApGain(rounds, diff, isBoss)；写入所有已镶嵌灵玉的 AP 字段',
      path: 'stat_data.主角.资产.灵玉库存.{灵玉名}.AP'
    },
    物品掉落: {
      formula: '查 boss_table[章节].bosses[name].drops 表',
      note: 'BOSS 战固定掉落 + LCG ≥ 61 时额外掉落稀有物',
      path: 'stat_data.主角.资产.背包'
    }
  },

  /* ════════════════════════════════════════════════════════════
     四、战斗状态变量更新路径
     ════════════════════════════════════════════════════════════ */
  state_paths: {
    'stat_data.战斗.敌方名':       '敌方NPC名称',
    'stat_data.战斗.敌方HP':       '敌方当前HP',
    'stat_data.战斗.敌方最大HP':   '敌方最大HP',
    'stat_data.战斗.回合数':       '当前回合数（每回合 +1）',
    'stat_data.战斗.是否BOSS战':   'true / false',
    'stat_data.战斗.战斗背景':     '场景标识',
    'stat_data.战斗.我方编成':     '我方参战角色数组',
    'stat_data.战斗.状态':         '未触发 / 进行中 / 胜利 / 失败 / 逃跑',
    'stat_data.战斗.难度':         '简单 / 普通 / 困难 / 噩梦',
    'stat_data.时间.当前时间':     '每回合 +30 分钟'
  },

  /* ════════════════════════════════════════════════════════════
     五、工具函数（供战斗结果处理器调用）
     ════════════════════════════════════════════════════════════ */
  lookupBoss: function (chapter, name) {
    var c = this.boss_table[Number(chapter)];
    if (!c) return null;
    for (var i = 0; i < c.bosses.length; i++) {
      if (c.bosses[i].name === name) return c.bosses[i];
    }
    return null;
  },

  calcExp: function (base, difficulty, lcgTier) {
    var diffMap = this.difficulty_coeff;
    var coeff = diffMap[difficulty] != null ? diffMap[difficulty] : 1.0;
    var tierMap = this.result_formula.经验值.tier_coeff;
    var tierCoeff = tierMap[lcgTier] != null ? tierMap[lcgTier] : 1.0;
    return Math.floor(Number(base) * coeff * tierCoeff);
  },

  calcGold: function (base, difficulty, isBoss) {
    var diffMap = this.difficulty_coeff;
    var coeff = diffMap[difficulty] != null ? diffMap[difficulty] : 1.0;
    var g = Math.floor(Number(base) * coeff);
    if (isBoss) g = Math.floor(g * 1.5);
    return g;
  },

  calcApGain: function (rounds, difficulty, isBoss) {
    if (typeof SPIRITE_JADE_SYSTEM !== 'undefined' && typeof SPIRITE_JADE_SYSTEM.calcApGain === 'function') {
      return SPIRITE_JADE_SYSTEM.calcApGain(rounds, difficulty, isBoss);
    }
    var diffMap = this.difficulty_coeff;
    var coeff = diffMap[difficulty] != null ? diffMap[difficulty] : 1.0;
    var gain = Number(rounds) * (1 + coeff);
    if (isBoss) gain = gain * 1.5;
    return Math.floor(gain);
  }
};

define('BATTLE_DISPATCHER', BATTLE_DISPATCHER);
