/* 条件评估器：解析 condition 字符串并返回布尔值 */
function ejf_evaluateCondition(condition, context) {
  if (condition === 'always') return true;

  /* scene_characters.length > 0 */
  if (condition === 'scene_characters.length > 0') {
    return context.scene_characters.length > 0;
  }
  /* party_names.length > 0 */
  if (condition === 'party_names.length > 0') {
    return context.party_names.length > 0;
  }
  /* current_dialogue_char > 0 */
  if (condition === 'current_dialogue_char > 0') {
    return context.current_dialogue_char > 0;
  }
  /* current_dialogue_char > N */
  if (condition.startsWith('current_dialogue_char > ')) {
    return context.current_dialogue_char > Number(condition.split('> ')[1]);
  }
  /* location.includes("关键词") */
  if (condition.startsWith('location.includes(')) {
    const _match = condition.match(/"([^"]+)"/);
    if (!_match) return false;
    return context.location.includes(_match[1]);
  }
  /* chapter == 章节名 */
  if (condition.startsWith('chapter == ')) {
    return context.chapter === condition.split('== ')[1];
  }
  return false;
}

/* 模块加载器：返回模块名与 getwi 路径列表（实际加载由调用方执行） */
function ejf_loadModule(module_name, context) {
  /* ── 动态模块：当前地点 ── */
  if (module_name === '当前地点') {
    let _modName = null;
    for (const _key in EJF_LOCATION_MAP) {
      if (context.location.includes(_key)) {
        _modName = EJF_LOCATION_MAP[_key];
        break;
      }
    }
    if (!_modName) _modName = '地理-余杭镇';
    const _path = EJF_MODULE_PATHS[_modName];
    return { name: module_name, paths: _path ? [_path] : [], dynamic: true, note: _modName || '未匹配' };
  }

  /* ── 动态模块：当前章节 ── */
  if (module_name === '当前章节') {
    let _modName = EJF_CHAPTER_MAP[context.chapter] || '章节-仙灵岛';
    const _path = EJF_MODULE_PATHS[_modName];
    return { name: module_name, paths: _path ? [_path] : [], dynamic: true, note: _modName };
  }

  /* ── 动态模块：当前场景人物4件套 ── */
  if (module_name === '当前场景人物4件套') {
    const _paths = [];
    const _names = [];
    for (const _charId of context.scene_characters) {
      const _id = Number(_charId);
      if (!_id) continue;
      const _charPaths = ejf_buildCharFourPack(_id);
      for (const _p of _charPaths) {
        _paths.push(_p);
      }
      _names.push(EJF_CHAR_MAP[_id] || ('ID:' + _id));
    }
    return { name: module_name, paths: _paths, dynamic: true, note: '人物: ' + _names.join(', ') };
  }

  /* ── 动态模块：队伍成员4件套 ── */
  if (module_name === '队伍成员4件套') {
    const _paths = [];
    const _names = [];
    for (const _name of context.party_names) {
      const _id = EJF_NAME_TO_ID[_name];
      if (!_id) continue;
      const _charPaths = ejf_buildCharFourPack(_id);
      for (const _p of _charPaths) {
        _paths.push(_p);
      }
      _names.push(_name);
    }
    return { name: module_name, paths: _paths, dynamic: true, note: '队伍: ' + _names.join(', ') };
  }

  /* ── 动态模块：队伍成员基础信息（仅基础信息，非4件套） ── */
  if (module_name === '队伍成员基础信息') {
    const _paths = [];
    const _names = [];
    for (const _name of context.party_names) {
      const _id = EJF_NAME_TO_ID[_name];
      if (!_id) continue;
      const _p = ejf_buildCharPath(_id, '基础信息');
      if (_p) _paths.push(_p);
      _names.push(_name);
    }
    return { name: module_name, paths: _paths, dynamic: true, note: '队伍基础: ' + _names.join(', ') };
  }

  /* ── 动态模块：当前对话人物4件套 ── */
  if (module_name === '当前对话人物4件套') {
    const _id = context.current_dialogue_char;
    if (!_id) return { name: module_name, paths: [], dynamic: true, note: '未指定对话人物' };
    const _charPaths = ejf_buildCharFourPack(_id);
    const _name = EJF_CHAR_MAP[_id] || ('ID:' + _id);
    return { name: module_name, paths: _charPaths, dynamic: true, note: '对话人物: ' + _name };
  }

  /* ── 动态模块：关系网基础信息（引用 stat_data.角色，无需 getwi） ── */
  if (module_name === '关系网基础信息') {
    return { name: module_name, paths: [], dynamic: true, note: '引用 stat_data.角色，无需 getwi 加载' };
  }

  /* ── 动态模块：当前炼丹配方（由蛊毒炼丹系统内部查询） ── */
  if (module_name === '当前炼丹配方') {
    return { name: module_name, paths: [], dynamic: true, note: '由蛊毒炼丹系统内部按 stat_data.场景.当前炼丹配方 查询' };
  }

  /* ── 静态模块：查 EJF_MODULE_PATHS ── */
  const _path = EJF_MODULE_PATHS[module_name];
  return {
    name: module_name,
    paths: _path ? [_path] : [],
    dynamic: false,
    note: _path ? '' : '模块路径待整合/创建'
  };
}

/* 精准加载函数：根据 scene_mode 加载所需模块 */
function ejf_loadRequiredModules(scene_mode, context) {
  const _strategy = EJS_LOAD_STRATEGY[scene_mode] || EJS_LOAD_STRATEGY['探索'];
  const _loaded = [];
  const _skipped = [];

  /* 1. 加载必需模块 */
  for (const _name of _strategy.required_modules) {
    const _mod = ejf_loadModule(_name, context);
    _loaded.push(_mod);
  }

  /* 2. 加载条件模块 */
  for (const _cond of _strategy.conditional_modules) {
    if (ejf_evaluateCondition(_cond.condition, context)) {
      const _mod = ejf_loadModule(_cond.module, context);
      _loaded.push(_mod);
    } else {
      _skipped.push({ module: _cond.module, condition: _cond.condition, reason: '条件不满足' });
    }
  }

  return {
    scene_mode: scene_mode,
    strategy_description: _strategy.description,
    loaded_modules: _loaded,
    skipped_modules: _skipped,
    estimated_tokens: _strategy.estimated_tokens
  };
}
